film = smoothstep(0.2, 1.8, fbm(4, 4, 6.2, 4))
drip = smoothstep(1.2, 2.1, fbm(80, 3, 2.8, 3))
smudge = smoothstep(0.8, 2.0, fbm(20, 20, 9.4, 3))
dirt = clamp(0.5 * film + 0.6 * drip, 0, 1)
c = lerp(set(0.10, 0.13, 0.14), set(0.32, 0.30, 0.27), 0.4 * dirt)
@ao = 1
@roughness = clamp(0.04 + 0.35 * dirt + 0.12 * smudge, 0, 1)
@metallic = 0
# the colours above are picked as display (sRGB) values; the layer is linear -- Write File encodes it to sRGB
@basecolor = clamp(c, 0, 1) ** 2.2

